// JavaScript code to calculate the number of columns
function calculateColumns(text, width, columns) {
  var words = text.split(' ');
  var columnsArray = [];
  var columnWidth = width / columns;

  for (var i = 0; i < columns; i++) {
    var columnText = '';
    var wordIndex = 0;

    while (wordIndex < words.length && words[wordIndex].length * columnWidth < width) {
      columnText += words[wordIndex] + ' ';
      wordIndex++;
    }

    columnsArray.push(columnText);
